    elif state["phase"] == "HOLD":
        x, y = pd[0], pd[1]
        if x >= 15.0 and 0.5 <= y <= 2.5:
            state["hold_steps"] = state.get("hold_steps", 0) + 1
        else:
            # If not in exit zone, transition back to ESCAPE
            state["phase"] = "ESCAPE"
            state["hold_steps"] = 0

    sandbox.apply_agent_force(fx, fy)

